#!/usr/bin/env node
// Builds the Python API reference (pdoc) for the openvireo package into public/reference/python/.
//
//   node scripts/apidocs/python.mjs                     # openvireo-core at origin/develop
//   node scripts/apidocs/python.mjs --ref v1.2.0        # any ref the core checkout knows
//
// The core checkout defaults to ../openvireo-core; OPENVIREO_CORE_SRC overrides it. The ref is
// `git archive`d into a temp dir and everything is built there, so the checkout is never touched.
//
// Half of the package (`openvireo._core`) is generated by UniFFI from bindings/ov-ffi and loads the
// native library, so pdoc can't import it from source alone: `maturin develop` (debug) builds the
// cdylib, runs the crate's own uniffi-bindgen and installs the package into a throwaway venv, then
// pdoc documents `openvireo` (which re-exports the whole generated API) and `openvireo.hosts`.
// Underscore modules (`_core`, `_compat`) are left out.
//
// Needs: git, cargo (the core's toolchain), and uv or a python3 >= 3.10 on PATH. pip installs
// maturin and pdoc into the venv. OPENVIREO_APIDOCS_CARGO_TARGET, when set, is used as
// CARGO_TARGET_DIR and kept, so repeat runs (and cpp.mjs) build incrementally.

import { execFileSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const outDir = join(root, 'public', 'reference', 'python');

let ref = 'origin/develop';
const args = process.argv.slice(2);
for (let i = 0; i < args.length; i++) {
    if (args[i] === '--ref') ref = args[++i];
    else if (args[i] === '-h' || args[i] === '--help') {
        console.log('Usage: node scripts/apidocs/python.mjs [--ref <ref>]   (env OPENVIREO_CORE_SRC, OPENVIREO_APIDOCS_CARGO_TARGET)');
        process.exit(0);
    } else fail(`unknown argument ${args[i]}`);
}
if (!ref) fail('--ref needs a value');

function fail(message) {
    console.error(`error: ${message}`);
    process.exit(1);
}

const run = (cmd, cmdArgs, opts = {}) =>
    execFileSync(cmd, cmdArgs, { stdio: ['ignore', 'inherit', 'inherit'], ...opts });
const capture = (cmd, cmdArgs, opts = {}) =>
    execFileSync(cmd, cmdArgs, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts }).trim();
const which = (bin) => {
    try {
        return capture('sh', ['-c', 'command -v "$1"', 'sh', bin]) || null;
    } catch {
        return null;
    }
};

const repo = resolve(process.env.OPENVIREO_CORE_SRC ?? join(root, '..', 'openvireo-core'));
if (!existsSync(join(repo, '.git'))) fail(`no git checkout at ${repo} (set OPENVIREO_CORE_SRC)`);
let commit;
try {
    commit = capture('git', ['-C', repo, 'rev-parse', '--verify', `${ref}^{commit}`]);
} catch {
    fail(`${repo} has no ref ${ref} (git fetch?)`);
}

const started = Date.now();
const work = mkdtempSync(join(tmpdir(), 'openvireo-pydoc-'));
try {
    console.log(`Python API reference from openvireo-core ${ref}@${commit.slice(0, 10)}`);
    const src = join(work, 'src');
    mkdirSync(src);
    execFileSync('sh', ['-c', 'git -C "$1" archive "$2" | tar -x -C "$3"', 'sh', repo, commit, src]);
    const project = join(src, 'bindings', 'python');
    if (!existsSync(join(project, 'pyproject.toml'))) fail(`openvireo-core at ${ref} has no bindings/python`);

    // A throwaway venv with maturin and pdoc.
    const venv = join(work, 'venv');
    const uv = which('uv');
    if (uv) {
        run(uv, ['venv', '--quiet', '--python', '3.12', venv]);
    } else {
        const python = ['python3.13', 'python3.12', 'python3.11', 'python3.10', 'python3']
            .map(which)
            .find((p) => p && capture(p, ['-c', 'import sys; print(sys.version_info >= (3, 10))']) === 'True');
        if (!python) fail('needs uv or a python3 >= 3.10 on PATH');
        run(python, ['-m', 'venv', venv]);
    }
    const bin = (name) => join(venv, process.platform === 'win32' ? 'Scripts' : 'bin', name);
    const env = { ...process.env, VIRTUAL_ENV: venv, PATH: `${dirname(bin('python'))}:${process.env.PATH}` };
    delete env.CONDA_PREFIX;
    env.CARGO_TARGET_DIR = process.env.OPENVIREO_APIDOCS_CARGO_TARGET
        ? resolve(process.env.OPENVIREO_APIDOCS_CARGO_TARGET)
        : join(work, 'target');
    // httpx and keyring are the package's optional extras: installed so openvireo.hosts' annotations resolve.
    const pipArgs = ['maturin>=1.9,<2.0', 'pdoc>=16,<17', 'httpx>=0.27', 'keyring>=24'];
    if (uv) run(uv, ['pip', 'install', '--quiet', '--python', bin('python'), ...pipArgs], { env });
    else run(bin('python'), ['-m', 'pip', 'install', '--quiet', '--disable-pip-version-check', ...pipArgs], { env });

    // Build the cdylib, generate openvireo._core and install the package (editable, in the temp dir).
    console.log('  maturin develop (cargo build of ov-ffi, uniffi-bindgen)…');
    const t0 = Date.now();
    run(bin('maturin'), ['develop', ...(uv ? ['--uv'] : []), '--quiet'], { cwd: project, env });
    console.log(`  built in ${Math.round((Date.now() - t0) / 1000)} s`);

    const version = capture(bin('python'), ['-c', 'import openvireo; print(openvireo.__version__)'], { cwd: work, env });

    // pdoc: the package (with everything it re-exports from _core) and its public submodule
    // openvireo.hosts; underscore modules are private to pdoc and skipped. The docstrings use reST
    // roles (:mod:, :func:). No "View Source": most of it is UniFFI's generated FFI plumbing.
    console.log('  pdoc…');
    const html = join(work, 'html');
    writeFileSync(join(work, 'pdoc_driver.py'), pdocDriver());
    run(
        bin('python'),
        [
            join(work, 'pdoc_driver.py'),
            'openvireo',
            '--no-show-source',
            '--output-directory', html,
            '--docformat', 'restructuredtext',
            '--footer-text', `${version === '0.0.0' ? 'openvireo' : `openvireo ${version}`}, openvireo-core ${ref} @ ${commit.slice(0, 10)}`,
            '--edit-url', `openvireo=https://github.com/openvireo/openvireo-core/blob/${commit}/bindings/python/python/openvireo/`,
        ],
        { cwd: work, env },
    );
    if (!existsSync(join(html, 'index.html'))) fail('pdoc wrote no index.html');

    rmSync(outDir, { recursive: true, force: true });
    mkdirSync(dirname(outDir), { recursive: true });
    cpSync(html, outDir, { recursive: true });

    const { files, bytes } = tally(outDir);
    console.log(
        `  Python API reference (openvireo ${version}): ${files} files, ${(bytes / 1048576).toFixed(1)} MB in public/reference/python/ ` +
            `(${Math.round((Date.now() - started) / 1000)} s)`,
    );
} finally {
    rmSync(work, { recursive: true, force: true });
}

function tally(dir) {
    let files = 0;
    let bytes = 0;
    for (const name of readdirSync(dir, { recursive: true })) {
        const st = statSync(join(dir, name));
        if (st.isFile()) {
            files++;
            bytes += st.size;
        }
    }
    return { files, bytes };
}

// pdoc, run through two patches (pdoc 16) for what the generated module does. Written into the
// temp dir and run with the venv's Python.
function pdocDriver() {
    return `import inspect
import sys

import pdoc.__main__
import pdoc.doc
import pdoc.doc_pyi

MARKER = "__ov_optional_cancel__"

# 1. UniFFI's error classes nest a subclass in its base (OvError.Failure inherits OvError, so
#    OvError.Failure.Failure is itself). pdoc's stub-file pass walks nested classes without a
#    visited set and recurses forever: visit each object once.
def _once(fn):
    seen = set()
    def wrapped(target, *args):
        key = id(getattr(target, "obj", target))
        if key in seen:
            return None
        seen.add(key)
        return fn(target, *args)
    return wrapped

pdoc.doc_pyi._prepare_module = _once(pdoc.doc_pyi._prepare_module)
pdoc.doc_pyi._patch_doc = _once(pdoc.doc_pyi._patch_doc)

# 2. openvireo._compat rewraps every call that takes a CancelToken so the token is optional, and
#    gives the wrapper the real signature (__signature__). pdoc unwraps __wrapped__ and would show
#    the generated, required one: document the original function with the wrapper's signature.
Function = pdoc.doc.Function
_init = Function.__init__
_signature = Function.signature.func

def _init_patched(self, modulename, qualname, func, taken_from):
    _init(self, modulename, qualname, func, taken_from)
    self._ov_sig_from = None
    if getattr(self.obj, MARKER, False):
        self._ov_sig_from = self.obj
        self.obj = inspect.unwrap(self.obj)
    elif getattr(getattr(func, "__func__", func), MARKER, False) or getattr(func, MARKER, False):
        self._ov_sig_from = getattr(func, "__func__", func)

def _signature_patched(self):
    source = getattr(self, "_ov_sig_from", None)
    if source is None:
        return _signature(self)
    real = self.obj
    self.obj = source
    try:
        return _signature(self)
    finally:
        self.obj = real

Function.__init__ = _init_patched
Function.signature = pdoc.doc.cached_property(_signature_patched)
Function.signature.__set_name__(Function, "signature")

sys.setrecursionlimit(5000)
pdoc.__main__.cli()
`;
}
